async function validarUrlExternaPermitida(rawUrl){if(!rawUrl||typeof rawUrl!=="string")return{ok:false,error:"URL requerida"};let u;try{u=new URL(rawUrl)}catch{return{ok:false,error:"URL invalida"}}if(u.protocol!=="http:"&&u.protocol!=="https:")return{ok:false,error:"Esquema no permitido"};const host=u.hostname.toLowerCase();if(host==="localhost"||host.endsWith(".local")||host.endsWith(".internal"))return{ok:false,error:"Host no permitido"};try{const results=await dns.promises.lookup(host,{all:true});if(!results||!results.length)return{ok:false,error:"Host no resuelve"};for(const r of results){if(ipEsPrivada(r.address))return{ok:false,error:"Destino interno bloqueado"}}}catch{return{ok:false,error:"No se pudo resolver el host"}}return{ok:true,url:u.toString()}}
function verificarFirmaMeta(req){const secret=process.env.WHATSAPP_APP_SECRET;if(!secret){const produccion=process.env.NODE_ENV==="production";return{ok:!produccion,warning:produccion?"Falta WHATSAPP_APP_SECRET (rechazado en produccion)":"Sin secreto configurado (modo dev)"}}const sig=String(req.headers["x-hub-signature-256"]||"");const raw=(req as any).rawBody;if(!raw||!sig.startsWith("sha256="))return{ok:false};const expected=crypto.createHmac("sha256",secret).update(raw).digest("hex");return{ok:compararHmacHex(sig.slice(7),expected)}}
function verificarSecretoWaha(req){const secret=process.env.WAHA_WEBHOOK_SECRET;if(!secret){const produccion=process.env.NODE_ENV==="production";return{ok:!produccion,warning:produccion?"Falta WAHA_WEBHOOK_SECRET (rechazado en produccion)":"Sin secreto configurado (modo dev)"}}const presented=String(req.headers["x-api-key"]||req.headers["x-webhook-secret"]||req.headers.authorization||"").replace(/^Bearer\s+/i,"");if(!presented)return{ok:false};const a=crypto.createHash("sha256").update(presented).digest("hex");const b=crypto.createHash("sha256").update(secret).digest("hex");return{ok:compararHmacHex(a,b)}}
