const AUTH_TOKEN_TTL_MS=30*24*60*60*1e3;let cachedAuthSecret=null;
function b64urlEncode(input){return Buffer.from(input).toString("base64").replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"")}
function b64urlDecode(str){return Buffer.from(String(str).replace(/-/g,"+").replace(/_/g,"/"),"base64").toString("utf8")}
async function getAuthSecret(){if(cachedAuthSecret)return cachedAuthSecret;try{let s=await getSetting("auth_secret",null);if(!s||typeof s!=="string"||s.length<32){s=crypto.randomBytes(48).toString("hex");await saveSetting("auth_secret",s);console.log("[Auth] Secreto HMAC generado y persistido en app_settings.")}cachedAuthSecret=s;return s}catch(err){console.warn("[Auth] No se pudo leer/crear secreto:",err);return process.env.AUTH_SECRET||"vuuy-dev-fallback-secret"}}
function hashPassword(password,salt){const s=salt||crypto.randomBytes(16).toString("hex");const hash=crypto.scryptSync(String(password),s,64).toString("hex");return{salt:s,hash:hash}}
function verifyPassword(password,salt,hash){try{const h=crypto.scryptSync(String(password),String(salt),64).toString("hex");const a=Buffer.from(h);const b=Buffer.from(String(hash));return a.length===b.length&&crypto.timingSafeEqual(a,b)}catch{return false}}
