async function seedAuthUsersIfNeeded(){const existing=await getAuthUsers();if(existing.length>0)return existing;const adminEmail=(process.env.VUUV_ADMIN_EMAIL||"admin@vuuy.pe").toLowerCase();const adminPass=process.env.VUUV_ADMIN_PASSWORD||crypto.randomBytes(9).toString("base64url");const a=hashPassword(adminPass);const list=[{email:adminEmail,passwordSalt:a.salt,passwordHash:a.hash,nombre:"Super Administrador",rol:"admin",usuarioId:"admin_master_01",descripcion:"Acceso total al Panel de Administracion"}];const cEmail=(process.env.VUUV_COMMERCE_EMAIL||"").toLowerCase();const cPass=process.env.VUUV_COMMERCE_PASSWORD;if(cEmail&&cPass){const c=hashPassword(cPass);list.push({email:cEmail,passwordSalt:c.salt,passwordHash:c.hash,nombre:process.env.VUUV_COMMERCE_NAME||"Comercio Aliado",rol:"comercio",usuarioId:"comercio_user_01",merchantId:process.env.VUUV_COMMERCE_ID||"merch_01",descripcion:"Acceso al Panel de Comercio"})}await saveSetting("auth_users",list);console.log("[Auth] Usuarios sembrados ("+list.length+"). Admin: "+adminEmail+" "+(process.env.VUUV_ADMIN_PASSWORD?"(clave desde env)":"(clave generada: "+adminPass+")"));return list}
async function findAuthUser(email){const list=await getAuthUsers();const target=String(email||"").trim().toLowerCase();return list.find(u=>String(u.email||"").toLowerCase()===target)||null}
async function signAuthToken(payload){const secret=await getAuthSecret();const body=b64urlEncode(JSON.stringify(payload));const sig=crypto.createHmac("sha256",secret).update(body).digest();return body+"."+b64urlEncode(sig)}
async function verifyAuthToken(token){try{if(!token||typeof token!=="string"||!token.includes("."))return null;const parts=token.split(".");const body=parts[0];const sig=parts[1];const secret=await getAuthSecret();const expected=b64urlEncode(crypto.createHmac("sha256",secret).update(body).digest());const a=Buffer.from(sig);const b=Buffer.from(expected);if(a.length!==b.length||!crypto.timingSafeEqual(a,b))return null;const payload=JSON.parse(b64urlDecode(body));if(!payload||!payload.exp||payload.exp<Date.now())return null;return payload}catch{return null}}
function extraerBearer(req){const h=req.headers&&(req.headers["authorization"]||req.headers["Authorization"]);if(typeof h==="string"&&h.toLowerCase().startsWith("bearer "))return h.slice(7).trim();return null}
function esRutaPublica(req){const rawPath=String(req.path||req.url||"").split("?")[0];const m=String(req.method||"GET").toUpperCase();if(rawPath==="/api/auth/login"&&m==="POST")return true;if(rawPath==="/api/auth/forgot-password"&&m==="POST")return true;if(rawPath==="/api/auth/reset-password"&&m==="POST")return true;if(rawPath==="/api/auth/me"&&m==="GET")return true;if(rawPath==="/api/version"&&m==="GET")return true;if(rawPath==="/api/whatsapp/public"&&m==="GET")return true;if(rawPath==="/api/banners"&&m==="GET")return true;if(rawPath==="/api/ofertas"&&m==="GET")return true;if(rawPath==="/api/ofertas/publicas"&&m==="GET")return true;if(/^\/api\/ofertas\/[^/]+\/like$/.test(rawPath)&&m==="POST")return true;if(/^\/api\/media\/video\/[^/]+$/.test(rawPath)&&m==="GET")return true;if(rawPath==="/api/whatsapp/webhook")return true;if(rawPath==="/api/waha/webhook")return true;if(rawPath==="/api/audience/check-uniqueness"&&m==="POST")return true;if(rawPath==="/api/audience/sync-user"&&m==="POST")return true;if(rawPath==="/api/audience/log-registration"&&m==="POST")return true;if(rawPath==="/api/audience/verify-token"&&m==="GET")return true;if(rawPath==="/api/verify-email"&&m==="GET")return true;if(rawPath==="/api/email/send-verification"&&m==="POST")return true;if(rawPath.startsWith("/api/go/"))return true;if(rawPath.startsWith("/go/"))return true;if(rawPath.startsWith("/c/"))return true;return false}
app.use(async(req,res,next)=>{try{if(!String(req.path||"").startsWith("/api"))return next();if(esRutaPublica(req))return next();const payload=await verifyAuthToken(extraerBearer(req));if(!payload){void logEventoSeguridad({accion:"Acceso denegado",entidad:"api",entidadId:String(req.path||""),detalles:"Sin token valido desde "+clienteIp(req)});res.status(401).json({ok:false,error:"No autorizado. Se requiere inicio de sesion."});return}(req as any).auth=payload;next()}catch(err){next(err)}});
async function requireAdmin(req,res,next){try{const payload=(req as any).auth||await verifyAuthToken(extraerBearer(req));if(!payload){res.status(401).json({ok:false,error:"No autorizado."});return}if(payload.rol!=="admin"){void logEventoSeguridad({operadorId:payload.usuarioId,operadorNombre:payload.nombre,accion:"Acceso denegado (rol)",entidad:"api",entidadId:String(req.path||""),detalles:"Rol "+payload.rol+" insuficiente"});res.status(403).json({ok:false,error:"Se requiere rol administrador."});return}(req as any).auth=payload;next()}catch(err){next(err)}}
function hashResetCode(email,codigo){return crypto.createHash("sha256").update(String(email||"").trim().toLowerCase()+":"+String(codigo||"")).digest("hex")}
