async function enviarCorreo(opts){const to=opts&&opts.to;const subject=(opts&&opts.subject)||"Sustrae Imprenta";const html=(opts&&opts.html)||"";try{if(emailConfig.provider==="resend"&&emailConfig.resend.apiKey){const sender=`${emailConfig.resend.fromName||"Sustrae Imprenta"} <${emailConfig.resend.fromEmail||"no-reply@mail.sustrae.com"}>`;const r=await fetch("https://api.resend.com/emails",{method:"POST",headers:{"Content-Type":"application/json","Authorization":`Bearer ${emailConfig.resend.apiKey}`},body:JSON.stringify({from:sender,to:[to],subject:subject,html:html})});const t=await r.text();if(!r.ok)return{ok:false,error:`Resend [HTTP ${r.status}]: ${String(t).slice(0,200)}`};return{ok:true,provider:"resend"}}if(emailConfig.provider==="smtp"&&emailConfig.smtp.host&&emailConfig.smtp.user&&emailConfig.smtp.pass){const transporter=nodemailer.createTransport({host:emailConfig.smtp.host,port:emailConfig.smtp.port,secure:emailConfig.smtp.secure,auth:{user:emailConfig.smtp.user,pass:emailConfig.smtp.pass}});await transporter.sendMail({from:`"${emailConfig.smtp.fromName}" <${emailConfig.smtp.fromEmail}>`,to:to,subject:subject,html:html});return{ok:true,provider:"smtp"}}return{ok:false,error:"Proveedor de correo no configurado"}}catch(e){return{ok:false,error:(e&&e.message)||"Error enviando correo"}}}
const loginFailState=new Map();
function loginBloqueadoSeg(email){const st=loginFailState.get(email);if(!st||!st.lockedUntil)return 0;const rem=st.lockedUntil-Date.now();if(rem<=0){loginFailState.delete(email);return 0}return Math.ceil(rem/1000)}
function registrarLoginFallido(email){const st=loginFailState.get(email)||{count:0,lockedUntil:0};st.count=(st.count||0)+1;if(st.count>=5){st.lockedUntil=Date.now()+15*60*1000;st.count=0;loginFailState.set(email,st);return true}loginFailState.set(email,st);return false}
function limpiarLoginFallido(email){loginFailState.delete(email)}
