app.post("/api/auth/forgot-password",rateLimit("reset",5,900000),async(req,res)=>{try{const email=String((req.body||{}).email||"").trim().toLowerCase();const genericMsg="Si el correo esta registrado, recibiras un codigo de recuperacion en tu bandeja.";if(!email){res.status(400).json({ok:false,error:"Debe ingresar un correo electronico."});return}const list=await getAuthUsers();const user=list.find(u=>String(u.email||"").toLowerCase()===email);if(!user){void logEventoSeguridad({accion:"Reset solicitado",entidad:"autenticacion",entidadId:email,detalles:"Correo no registrado (respuesta generica)"});res.json({ok:true,mensaje:genericMsg});return}const codigo=crypto.randomBytes(4).toString("hex").toUpperCase();const exp=Date.now()+15*60*1000;const tokens=(await getResetTokens()).filter(t=>String(t.email||"").toLowerCase()!==email);tokens.push({email:email,hash:hashResetCode(email,codigo),exp:exp,creadoEn:Date.now()});await saveResetTokens(tokens);const html=`<div style="font-family:Arial,sans-serif;max-width:520px;margin:0 auto;padding:24px;color:#1c1917"><h2 style="color:#1B4332">Recuperacion de contrasena</h2><p>Hola, recibimos una solicitud para restablecer la contrasena de tu cuenta en Sustrae Imprenta.</p><p style="font-size:15px">Tu codigo de verificacion es:</p><div style="font-size:28px;font-weight:bold;letter-spacing:6px;background:#F5F3EC;padding:14px 20px;border-radius:12px;text-align:center;color:#0F172A">${codigo}</div><p style="color:#57534e;font-size:13px;margin-top:16px">El codigo vence en 15 minutos. Si no solicitaste este cambio, puedes ignorar este correo.</p><hr style="border:none;border-top:1px solid #EAE5D9;margin:20px 0"/><p style="color:#a8a29e;font-size:12px">Sustrae Imprenta - Seguridad de la cuenta</p></div>`;const envio=await enviarCorreo({to:email,subject:"Codigo de recuperacion de contrasena - Sustrae Imprenta",html:html});if(!envio.ok){console.warn("[Auth] No se pudo enviar codigo de reset a "+email+": "+envio.error+". Codigo temporal: "+codigo)}void logEventoSeguridad({accion:"Reset solicitado",entidad:"autenticacion",entidadId:email,detalles:envio.ok?"Codigo enviado por "+envio.provider:"Sin proveedor de correo configurado; codigo generado"});res.json({ok:true,mensaje:genericMsg})}catch(err){console.error("[Auth] Error en forgot-password:",err);res.status(500).json({ok:false,error:"Error procesando la solicitud."})}});
